import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(p,'utf8'),json=p=>JSON.parse(read(p));
const dir='content/uc3m/tema-19/';
const manual=read(dir+'manual.md'),sources=read(dir+'fuentes.md');
const matrix=json(dir+'matriz.json'),bank=json(dir+'preguntas.json');
const report=read(dir+'cotejo-integral-2026-11-04.md');
const acta=read('content/uc3m/CIERRE_DOCUMENTAL_T19_20261106.md');
const extra=json('data/uc3m-repaso-presupuesto-contratacion-t18-t20-20261106.json').preguntas.filter(q=>q.tema===19);
assert.equal(matrix.estado,'AUDITADO','T19 ya auditado editorialmente');
assert.equal(matrix.cobertura.length,6);
assert.equal(bank.preguntas.length,12);
const heads=[...manual.matchAll(/^## (\d+)\. /gm)].map(x=>Number(x[1])).filter(x=>x<=22);
assert.deepEqual([...new Set(heads)],Array.from({length:22},(_,i)=>i+1));
assert.ok(manual.includes('CIERRE_DOCUMENTAL_T19_20261106.md'));
assert.ok(sources.includes('CIERRE_DOCUMENTAL_T19_20261106.md'));
assert.ok(manual.includes('**documento O**')||manual.includes('**O**'));
assert.ok(manual.includes('**propuesta de pago**'));
assert.ok(manual.includes('**12.000 €**')||manual.includes('12.000 €'));
assert.ok(manual.includes('art. 198')||manual.includes('198.4'));
assert.ok(sources.includes('BOE-A-2017-12902')||sources.includes('Ley 9/2017'));
assert.ok(acta.includes('15 preguntas interactivas y 60 alternativas'));
assert.equal(extra.length,3);
const ids=new Set();
for(const q of bank.preguntas){
 assert.ok(q.id&&!ids.has(q.id),'Identificador repetido '+q.id);ids.add(q.id);
 assert.equal(q.opciones.length,4);assert.equal(new Set(q.opciones).size,4);
 assert.ok(q.opciones.every(s=>typeof s==='string'&&s.trim()));
 assert.ok(Number.isInteger(q.correcta)&&q.correcta>=0&&q.correcta<4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampa&&q.referencia);
 assert.ok(q.referencia.includes('https://'),'Falta fuente '+q.id);
 assert.ok(report.includes('### '+q.id+' — '+q.pregunta),'Falta cotejo individual '+q.id);
}
const articles=['15.2.1','16.3','198.5'];
for(const [i,q] of extra.entries()){
 assert.ok(!ids.has(q.id));ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones).size,4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampaExamen&&q.fundamento&&q.referencia);
 assert.ok(q.referencia.includes('art. '+articles[i]),'Articulo extra incorrecto '+q.id);
}
const close=matrix.cierreDocumentalT19_20261106;
assert.equal(close?.resultado,'CIERRE_DOCUMENTAL_REGISTRADO_CON_RESERVAS');
assert.equal(close?.bloquesMatriz,6);
assert.equal(close?.preguntasOriginales,12);
assert.equal(close?.alternativasOriginales,48);
assert.equal(close?.preguntasComplementarias,3);
assert.equal(close?.alternativasComplementarias,12);
assert.equal(close?.ejercicios,15);
assert.equal(close?.alternativas,60);
assert.equal(close?.aprobacionUsuario,false);
assert.equal(close?.certificacionIntegral,false);
assert.equal(close?.ciPendiente,true);
assert.equal(close?.navegadorE2E,false);
assert.ok(read('content/uc3m/GUIA_EXAMEN_2026.md').includes('CIERRE_DOCUMENTAL_T19_20261106.md'));
assert.ok(read('AUDITORIA_CONTINUA.md').includes('CIERRE_DOCUMENTAL_T19_20261106.md'));
assert.equal(ids.size,15);
console.log('UC3M T19: 6 BLOQUES, 12+3 PREGUNTAS, 60 ALTERNATIVAS, DOCUMENTO O Y LCSP 198, CON RESERVAS');
